import { createServerClient } from "@supabase/ssr";
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

export async function proxy(req: NextRequest) {
  const res = NextResponse.next();

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        get(name) {
          return req.cookies.get(name)?.value;
        },
        set(name, value, options) {
          res.cookies.set({ name, value, ...options });
        },
        remove(name, options) {
          res.cookies.set({ name, value: "", ...options });
        },
      },
    }
  );

  const {
    data: { session },
  } = await supabase.auth.getSession();

  // Routes qui nécessitent d'être connecté
  const authenticatedPaths = ["/profil", "/dashboard", "/admin"];

  const isAuthenticatedRoute = authenticatedPaths.some((path) =>
    req.nextUrl.pathname.startsWith(path)
  );

  if (isAuthenticatedRoute && !session) {
    return NextResponse.redirect(new URL("/login", req.url));
  }

  // Pour les routes admin, vérifier le flag is_admin
  if (req.nextUrl.pathname.startsWith("/admin")) {
    if (session) {
      // Récupérer le profil pour savoir si is_admin = true
      const { data: profile, error } = await supabase
        .from("profiles")
        .select("is_admin")
        .eq("id", session.user.id)
        .single();

      if (error || !profile || !profile.is_admin) {
        // Pas admin → redirection vers la page d'accueil
        return NextResponse.redirect(new URL("/", req.url));
      }
    }
  }

  return res;
}

export const config = {
  matcher: ["/profil/:path*", "/dashboard/:path*", "/admin/:path*"],
};